#!/usr/bin/env node
/**
 * Lesson-Capture Stop Gate
 *
 * Fires on Stop event. Scans the active session transcript for correction
 * signals. If signals are present and tasks/lessons.md has not been updated
 * within the session window, blocks the Stop with exit 2.
 *
 * Escape hatch: a `## Session Exemptions` heading in lessons.md with a
 * recent mtime bypasses the block.
 *
 * Infrastructure failures (missing transcript, unreadable files) never
 * block — they log to stderr and exit 0.
 */

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');

// ---------- Correction signal sets ----------

const USER_SIGNALS = [
  "you're wrong",
  "that's wrong",
  "no,",
  "incorrect",
  "don't",
  "stop",
  "actually",
  "re-read",
  "you missed",
  "try again",
  "that's not",
  "i said",
  "correction",
];

const ASSISTANT_SIGNALS = [
  "you're right",
  "my mistake",
  "i was wrong",
  "correcting",
  "let me fix",
];

const FOUR_HOURS_MS = 4 * 3600 * 1000;

// ---------- Pure helpers (exported for tests) ----------

/**
 * Strip fenced code blocks and inline backtick spans from text so
 * signal phrases inside code samples don't trigger false positives.
 */
function stripCode(text) {
  if (typeof text !== 'string') return '';
  return text
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/~~~[\s\S]*?~~~/g, ' ')
    .replace(/`[^`]*`/g, ' ');
}

/**
 * Count distinct correction signals in a list of messages.
 * Dedup is per (message_index, phrase) pair — the same phrase repeated
 * inside one message counts once.
 *
 * @param {Array<{role: 'user'|'assistant', content: string}>} messages
 * @returns {number}
 */
function countSignals(messages) {
  let total = 0;
  for (let i = 0; i < messages.length; i++) {
    const msg = messages[i];
    if (!msg || typeof msg.content !== 'string') continue;
    const cleaned = stripCode(msg.content).toLowerCase();
    const phrases = msg.role === 'assistant' ? ASSISTANT_SIGNALS : USER_SIGNALS;
    const matched = new Set();
    for (const phrase of phrases) {
      if (cleaned.includes(phrase)) matched.add(phrase);
    }
    total += matched.size;
  }
  return total;
}

/**
 * Decide whether lessons.md counts as "updated in the current session".
 *
 * Preferred: compare lessons.md mtime against the first transcript line's
 * timestamp. If the timestamp is unparseable, fall back to a 4-hour window
 * from now.
 *
 * @param {string} lessonsPath
 * @param {string|null} firstTimestamp - ISO string or null
 * @param {number} [now=Date.now()]
 * @returns {{updated: boolean, lessonsMtimeMs: number|null, reason: string}}
 */
function checkLessonsWindow(lessonsPath, firstTimestamp, now = Date.now()) {
  let lessonsMtimeMs = null;
  try {
    lessonsMtimeMs = fs.statSync(lessonsPath).mtimeMs;
  } catch (_err) {
    return { updated: false, lessonsMtimeMs: null, reason: 'lessons-missing' };
  }

  let startMs = null;
  if (firstTimestamp) {
    const parsed = Date.parse(firstTimestamp);
    if (!Number.isNaN(parsed)) startMs = parsed;
  }

  if (startMs !== null) {
    return {
      updated: lessonsMtimeMs >= startMs,
      lessonsMtimeMs,
      reason: 'timestamp-window',
    };
  }

  // Fallback: 4-hour window from now
  return {
    updated: now - lessonsMtimeMs < FOUR_HOURS_MS,
    lessonsMtimeMs,
    reason: 'fallback-4h',
  };
}

/**
 * Derive the Claude Code project slug from a working directory path.
 * Trailing slashes are normalized. Matches Claude Code's own scheme:
 * "-" + cwd.replaceAll('/', '-').
 */
function deriveSlug(cwd) {
  let normalized = String(cwd || '');
  // Strip trailing slashes (but keep root "/")
  while (normalized.length > 1 && normalized.endsWith('/')) {
    normalized = normalized.slice(0, -1);
  }
  return '-' + normalized.replaceAll('/', '-');
}

/**
 * Parse a JSONL transcript string into a list of {role, content} messages
 * plus the first line's timestamp (if any). Malformed lines are skipped.
 *
 * @param {string} raw
 * @returns {{messages: Array<{role: string, content: string}>, firstTimestamp: string|null}}
 */
function parseTranscript(raw) {
  const messages = [];
  let firstTimestamp = null;
  if (!raw) return { messages, firstTimestamp };

  const lines = raw.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch (_err) {
      continue;
    }

    if (firstTimestamp === null) {
      firstTimestamp = obj.timestamp || obj.ts || null;
    }

    // Claude Code transcripts: {type: "user"|"assistant", message: {role, content}}
    // Also support simpler {role, content} shapes for tests.
    const role = obj.role || (obj.message && obj.message.role) || obj.type;
    if (role !== 'user' && role !== 'assistant') continue;

    const rawContent = obj.content !== undefined
      ? obj.content
      : (obj.message && obj.message.content);

    let contentText = '';
    if (typeof rawContent === 'string') {
      contentText = rawContent;
    } else if (Array.isArray(rawContent)) {
      contentText = rawContent
        .map(part => (typeof part === 'string' ? part : (part && part.text) || ''))
        .join('\n');
    }
    messages.push({ role, content: contentText });
  }

  return { messages, firstTimestamp };
}

// ---------- Transcript location ----------

function findFallbackTranscript(cwd) {
  const slug = deriveSlug(cwd);
  const dir = path.join(os.homedir(), '.claude', 'projects', slug);
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (_err) {
    return null;
  }
  const jsonls = entries
    .filter(n => n.endsWith('.jsonl'))
    .map(n => {
      const full = path.join(dir, n);
      try {
        return { full, mtime: fs.statSync(full).mtimeMs };
      } catch (_err) {
        return null;
      }
    })
    .filter(Boolean)
    .sort((a, b) => b.mtime - a.mtime);
  return jsonls.length ? jsonls[0].full : null;
}

// ---------- Session Exemptions check ----------

function hasValidExemption(lessonsPath, firstTimestamp, now = Date.now()) {
  let raw;
  try {
    raw = fs.readFileSync(lessonsPath, 'utf8');
  } catch (_err) {
    return false;
  }
  if (!/^##\s+Session Exemptions/im.test(raw)) return false;
  const { updated } = checkLessonsWindow(lessonsPath, firstTimestamp, now);
  return updated;
}

// ---------- Debug log ----------

function writeDebugLog(entry) {
  try {
    const logPath = path.join(process.cwd(), '.claude', 'hooks', 'lesson-capture-gate.log');
    fs.mkdirSync(path.dirname(logPath), { recursive: true });
    fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');
  } catch (_err) {
    // Logging must never block the hook
  }
}

// ---------- Main ----------

function main() {
  // Read JSON payload from stdin
  let payload = {};
  try {
    const raw = fs.readFileSync(0, 'utf8');
    if (raw.trim()) payload = JSON.parse(raw);
  } catch (_err) {
    payload = {};
  }

  const cwd = process.cwd();
  let transcriptPath = payload.transcript_path || null;
  if (!transcriptPath || !fs.existsSync(transcriptPath)) {
    transcriptPath = findFallbackTranscript(cwd);
  }

  if (!transcriptPath) {
    process.stderr.write('lesson-capture-gate: no transcript found, skipping scan\n');
    writeDebugLog({
      ts: new Date().toISOString(),
      signals: 0,
      lessons_mtime: null,
      transcript: null,
      decision: 'allow',
      reason: 'no-transcript',
    });
    process.exit(0);
  }

  let transcriptRaw;
  try {
    transcriptRaw = fs.readFileSync(transcriptPath, 'utf8');
  } catch (_err) {
    process.stderr.write('lesson-capture-gate: transcript unreadable, skipping scan\n');
    writeDebugLog({
      ts: new Date().toISOString(),
      signals: 0,
      lessons_mtime: null,
      transcript: transcriptPath,
      decision: 'allow',
      reason: 'transcript-unreadable',
    });
    process.exit(0);
  }

  const { messages, firstTimestamp } = parseTranscript(transcriptRaw);
  const signals = countSignals(messages);
  const lessonsPath = path.join(cwd, 'tasks', 'lessons.md');
  const { updated, lessonsMtimeMs } = checkLessonsWindow(lessonsPath, firstTimestamp);

  if (signals === 0) {
    writeDebugLog({
      ts: new Date().toISOString(),
      signals,
      lessons_mtime: lessonsMtimeMs,
      transcript: transcriptPath,
      decision: 'allow',
      reason: 'no-signals',
    });
    process.exit(0);
  }

  if (updated) {
    writeDebugLog({
      ts: new Date().toISOString(),
      signals,
      lessons_mtime: lessonsMtimeMs,
      transcript: transcriptPath,
      decision: 'allow',
      reason: 'lessons-updated',
    });
    process.exit(0);
  }

  if (hasValidExemption(lessonsPath, firstTimestamp)) {
    writeDebugLog({
      ts: new Date().toISOString(),
      signals,
      lessons_mtime: lessonsMtimeMs,
      transcript: transcriptPath,
      decision: 'allow',
      reason: 'session-exemption',
    });
    process.exit(0);
  }

  const msg =
    `LESSON CAPTURE GATE: ${signals} correction signals detected in this session ` +
    `and tasks/lessons.md has no new entries.\n` +
    `Run the lesson-capture subagent before closing the session:\n` +
    `  Task tool → lesson-capture-subagent\n` +
    `Or append a single-line justification to tasks/lessons.md under a ` +
    `"## Session Exemptions" section.\n`;
  process.stderr.write(msg);
  writeDebugLog({
    ts: new Date().toISOString(),
    signals,
    lessons_mtime: lessonsMtimeMs,
    transcript: transcriptPath,
    decision: 'block',
    reason: 'signals-no-capture',
  });
  process.exit(2);
}

// ---------- Exports for tests ----------

exports.stripCode = stripCode;
exports.countSignals = countSignals;
exports.checkLessonsWindow = checkLessonsWindow;
exports.deriveSlug = deriveSlug;
exports.parseTranscript = parseTranscript;

if (require.main === module) {
  main();
}

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

const HOOK_PATH = path.resolve(__dirname, '..', '.claude', 'hooks', 'lesson-capture-gate.cjs');
const {
  stripCode,
  countSignals,
  checkLessonsWindow,
  deriveSlug,
  parseTranscript,
} = require(HOOK_PATH);

// ---------- Fixture helpers ----------

function makeSandbox() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lcg-'));
  fs.mkdirSync(path.join(dir, 'tasks'), { recursive: true });
  fs.mkdirSync(path.join(dir, '.claude', 'hooks'), { recursive: true });
  return dir;
}

function writeLessons(dir, content, mtimeMs) {
  const p = path.join(dir, 'tasks', 'lessons.md');
  fs.writeFileSync(p, content);
  if (mtimeMs !== undefined) {
    const t = new Date(mtimeMs);
    fs.utimesSync(p, t, t);
  }
  return p;
}

function writeTranscript(dir, lines) {
  const p = path.join(dir, 'transcript.jsonl');
  fs.writeFileSync(p, lines.map(l => (typeof l === 'string' ? l : JSON.stringify(l))).join('\n'));
  return p;
}

function runHook(dir, payload) {
  return spawnSync('node', [HOOK_PATH], {
    cwd: dir,
    input: JSON.stringify(payload || {}),
    encoding: 'utf8',
  });
}

function userMsg(text, ts) {
  const o = { type: 'user', message: { role: 'user', content: text } };
  if (ts) o.timestamp = ts;
  return o;
}

function asstMsg(text, ts) {
  const o = { type: 'assistant', message: { role: 'assistant', content: text } };
  if (ts) o.timestamp = ts;
  return o;
}

// ---------- Pure function tests ----------

test('stripCode removes triple-backtick fenced blocks', () => {
  const input = "before ```\nyou're wrong\n``` after";
  assert.ok(!stripCode(input).toLowerCase().includes("you're wrong"));
});

test('stripCode removes triple-tilde fenced blocks', () => {
  const input = "before ~~~\nyou're wrong\n~~~ after";
  assert.ok(!stripCode(input).toLowerCase().includes("you're wrong"));
});

test('stripCode removes inline backtick spans', () => {
  const input = "before `no,` after";
  assert.ok(!stripCode(input).toLowerCase().includes('no,'));
});

test('deriveSlug: basic cwd', () => {
  assert.equal(deriveSlug('/Users/foo/projects/Bar'), '-Users-foo-projects-Bar');
});

test('deriveSlug: trailing slash is stripped', () => {
  assert.equal(deriveSlug('/Users/foo/projects/Bar/'), '-Users-foo-projects-Bar');
});

test('countSignals: dedup within a single message', () => {
  const msgs = [
    { role: 'user', content: "you're wrong you're wrong you're wrong you're wrong you're wrong" },
  ];
  assert.equal(countSignals(msgs), 1);
});

test('countSignals: case-insensitive match', () => {
  const lower = countSignals([{ role: 'user', content: "you're wrong" }]);
  const upper = countSignals([{ role: 'user', content: "YOU'RE WRONG" }]);
  assert.equal(lower, 1);
  assert.equal(upper, 1);
});

test('countSignals: sums across user and assistant turns', () => {
  const msgs = [
    { role: 'user', content: "that's wrong" },
    { role: 'assistant', content: "my mistake, let me fix this" },
  ];
  // user: "that's wrong" = 1; assistant: "my mistake" + "let me fix" = 2
  assert.equal(countSignals(msgs), 3);
});

test('countSignals: fenced code with signal is ignored', () => {
  const msgs = [
    { role: 'user', content: "here is the log: ```\nError: you're wrong input\n```" },
  ];
  assert.equal(countSignals(msgs), 0);
});

test('parseTranscript: skips malformed JSON lines without crashing', () => {
  const raw = [
    JSON.stringify(userMsg("that's wrong", '2026-04-09T10:00:00Z')),
    '{ not valid json',
    JSON.stringify(asstMsg('my mistake')),
  ].join('\n');
  const { messages, firstTimestamp } = parseTranscript(raw);
  assert.equal(messages.length, 2);
  assert.equal(firstTimestamp, '2026-04-09T10:00:00Z');
});

test('parseTranscript: empty input yields no messages', () => {
  const { messages, firstTimestamp } = parseTranscript('');
  assert.equal(messages.length, 0);
  assert.equal(firstTimestamp, null);
});

test('checkLessonsWindow: unparseable timestamp falls back to 4h window', () => {
  const dir = makeSandbox();
  const now = Date.now();
  const lessonsPath = writeLessons(dir, '# Lessons\n', now - 60 * 1000);
  const res = checkLessonsWindow(lessonsPath, 'not-a-date', now);
  assert.equal(res.reason, 'fallback-4h');
  assert.equal(res.updated, true);
});

test('checkLessonsWindow: >4h old with unparseable timestamp is not updated', () => {
  const dir = makeSandbox();
  const now = Date.now();
  const lessonsPath = writeLessons(dir, '# Lessons\n', now - 5 * 3600 * 1000);
  const res = checkLessonsWindow(lessonsPath, null, now);
  assert.equal(res.reason, 'fallback-4h');
  assert.equal(res.updated, false);
});

// ---------- Integration tests (spawned hook) ----------

test('zero correction signals → exit 0', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg('please add a feature', '2026-04-09T10:00:00Z'),
    asstMsg('done'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 0, res.stderr);
});

test('signals present + lessons newer than transcript start → exit 0', () => {
  const dir = makeSandbox();
  // Transcript says session started at T0; lessons.md is newer.
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  writeLessons(dir, '# Lessons\n- learned something new\n', sessionStart + 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("you're wrong", '2026-04-09T10:00:00Z'),
    asstMsg('fixed'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 0, res.stderr);
});

test('signals present + lessons unchanged in session → exit 2', () => {
  const dir = makeSandbox();
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  // lessons.md is OLDER than session start.
  writeLessons(dir, '# Lessons\n', sessionStart - 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("you're wrong", '2026-04-09T10:00:00Z'),
    asstMsg('ack'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 2);
  assert.match(res.stderr, /LESSON CAPTURE GATE/);
  assert.match(res.stderr, /1 correction signals/);
});

test('missing transcript payload AND no fallback → exit 0 with warning', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  // No transcript_path, and HOME pointed at a clean tmp dir so fallback glob is empty.
  const cleanHome = fs.mkdtempSync(path.join(os.tmpdir(), 'lcg-home-'));
  const res = spawnSync('node', [HOOK_PATH], {
    cwd: dir,
    input: '{}',
    encoding: 'utf8',
    env: { ...process.env, HOME: cleanHome },
  });
  assert.equal(res.status, 0);
  assert.match(res.stderr, /no transcript found/);
});

test('session exemptions heading + recent mtime → exit 0 despite signals', () => {
  const dir = makeSandbox();
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  const content = '# Lessons\n\n## Session Exemptions\n- 2026-04-09: no actionable rule\n';
  writeLessons(dir, content, sessionStart + 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("that's wrong", '2026-04-09T10:00:00Z'),
    asstMsg('ok'),
  ]);
  // Roll back lessons mtime to BEFORE session start but add exemption — should still block
  // because exemption requires window check to pass. So test the PASS path: keep mtime recent.
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 0, res.stderr);
});

test('payload transcript_path wins over fallback glob', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  // Create a "fallback" transcript in a fake HOME that WOULD trigger block
  const fakeHome = fs.mkdtempSync(path.join(os.tmpdir(), 'lcg-home-'));
  const slug = '-' + dir.replaceAll('/', '-');
  const fakeProjDir = path.join(fakeHome, '.claude', 'projects', slug);
  fs.mkdirSync(fakeProjDir, { recursive: true });
  fs.writeFileSync(
    path.join(fakeProjDir, 'bad.jsonl'),
    JSON.stringify(userMsg("you're wrong", '2020-01-01T00:00:00Z')) + '\n'
  );
  // Payload points at a CLEAN transcript with no signals
  const goodTranscript = writeTranscript(dir, [
    userMsg('hello', '2026-04-09T10:00:00Z'),
  ]);
  const res = spawnSync('node', [HOOK_PATH], {
    cwd: dir,
    input: JSON.stringify({ transcript_path: goodTranscript }),
    encoding: 'utf8',
    env: { ...process.env, HOME: fakeHome },
  });
  assert.equal(res.status, 0, res.stderr);
});

test('debug log written on allow path', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  const transcript = writeTranscript(dir, [userMsg('hi', '2026-04-09T10:00:00Z')]);
  runHook(dir, { transcript_path: transcript });
  const logPath = path.join(dir, '.claude', 'hooks', 'lesson-capture-gate.log');
  assert.ok(fs.existsSync(logPath), 'debug log should exist');
  const lines = fs.readFileSync(logPath, 'utf8').trim().split('\n');
  const entry = JSON.parse(lines[lines.length - 1]);
  assert.equal(entry.decision, 'allow');
});

test('debug log written on block path', () => {
  const dir = makeSandbox();
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  writeLessons(dir, '# Lessons\n', sessionStart - 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("you're wrong", '2026-04-09T10:00:00Z'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 2);
  const logPath = path.join(dir, '.claude', 'hooks', 'lesson-capture-gate.log');
  const lines = fs.readFileSync(logPath, 'utf8').trim().split('\n');
  const entry = JSON.parse(lines[lines.length - 1]);
  assert.equal(entry.decision, 'block');
  assert.equal(entry.signals, 1);
});

test('malformed JSONL line does not crash the hook', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  const p = path.join(dir, 'transcript.jsonl');
  fs.writeFileSync(
    p,
    [
      JSON.stringify(userMsg('hello', '2026-04-09T10:00:00Z')),
      '{ not valid',
      JSON.stringify(asstMsg('world')),
    ].join('\n')
  );
  const res = runHook(dir, { transcript_path: p });
  assert.equal(res.status, 0, res.stderr);
});

test('empty transcript file → exit 0', () => {
  const dir = makeSandbox();
  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
  const p = path.join(dir, 'transcript.jsonl');
  fs.writeFileSync(p, '');
  const res = runHook(dir, { transcript_path: p });
  assert.equal(res.status, 0, res.stderr);
});

test('uppercase correction signal triggers block', () => {
  const dir = makeSandbox();
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  writeLessons(dir, '# Lessons\n', sessionStart - 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("YOU'RE WRONG about this", '2026-04-09T10:00:00Z'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 2);
});

test('signals in fenced code block do NOT trigger block', () => {
  const dir = makeSandbox();
  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
  writeLessons(dir, '# Lessons\n', sessionStart - 60 * 1000);
  const transcript = writeTranscript(dir, [
    userMsg("look at this log:\n```\nno, don't do that\n```", '2026-04-09T10:00:00Z'),
  ]);
  const res = runHook(dir, { transcript_path: transcript });
  assert.equal(res.status, 0, res.stderr);
});

