  1→#!/usr/bin/env node
  2→/**
  3→ * Lesson-Capture Stop Gate
  4→ *
  5→ * Fires on Stop event. Scans the active session transcript for correction
  6→ * signals. If signals are present and tasks/lessons.md has not been updated
  7→ * within the session window, blocks the Stop with exit 2.
  8→ *
  9→ * Escape hatch: a `## Session Exemptions` heading in lessons.md with a
 10→ * recent mtime bypasses the block.
 11→ *
 12→ * Infrastructure failures (missing transcript, unreadable files) never
 13→ * block — they log to stderr and exit 0.
 14→ */
 15→
 16→'use strict';
 17→
 18→const fs = require('fs');
 19→const path = require('path');
 20→const os = require('os');
 21→
 22→// ---------- Correction signal sets ----------
 23→
 24→const USER_SIGNALS = [
 25→  "you're wrong",
 26→  "that's wrong",
 27→  "no,",
 28→  "incorrect",
 29→  "don't",
 30→  "stop",
 31→  "actually",
 32→  "re-read",
 33→  "you missed",
 34→  "try again",
 35→  "that's not",
 36→  "i said",
 37→  "correction",
 38→];
 39→
 40→const ASSISTANT_SIGNALS = [
 41→  "you're right",
 42→  "my mistake",
 43→  "i was wrong",
 44→  "correcting",
 45→  "let me fix",
 46→];
 47→
 48→const FOUR_HOURS_MS = 4 * 3600 * 1000;
 49→
 50→// ---------- Pure helpers (exported for tests) ----------
 51→
 52→/**
 53→ * Strip fenced code blocks and inline backtick spans from text so
 54→ * signal phrases inside code samples don't trigger false positives.
 55→ */
 56→function stripCode(text) {
 57→  if (typeof text !== 'string') return '';
 58→  return text
 59→    .replace(/```[\s\S]*?```/g, ' ')
 60→    .replace(/~~~[\s\S]*?~~~/g, ' ')
 61→    .replace(/`[^`]*`/g, ' ');
 62→}
 63→
 64→/**
 65→ * Count distinct correction signals in a list of messages.
 66→ * Dedup is per (message_index, phrase) pair — the same phrase repeated
 67→ * inside one message counts once.
 68→ *
 69→ * @param {Array<{role: 'user'|'assistant', content: string}>} messages
 70→ * @returns {number}
 71→ */
 72→function countSignals(messages) {
 73→  let total = 0;
 74→  for (let i = 0; i < messages.length; i++) {
 75→    const msg = messages[i];
 76→    if (!msg || typeof msg.content !== 'string') continue;
 77→    const cleaned = stripCode(msg.content).toLowerCase();
 78→    const phrases = msg.role === 'assistant' ? ASSISTANT_SIGNALS : USER_SIGNALS;
 79→    const matched = new Set();
 80→    for (const phrase of phrases) {
 81→      if (cleaned.includes(phrase)) matched.add(phrase);
 82→    }
 83→    total += matched.size;
 84→  }
 85→  return total;
 86→}
 87→
 88→/**
 89→ * Decide whether lessons.md counts as "updated in the current session".
 90→ *
 91→ * Preferred: compare lessons.md mtime against the first transcript line's
 92→ * timestamp. If the timestamp is unparseable, fall back to a 4-hour window
 93→ * from now.
 94→ *
 95→ * @param {string} lessonsPath
 96→ * @param {string|null} firstTimestamp - ISO string or null
 97→ * @param {number} [now=Date.now()]
 98→ * @returns {{updated: boolean, lessonsMtimeMs: number|null, reason: string}}
 99→ */
100→function checkLessonsWindow(lessonsPath, firstTimestamp, now = Date.now()) {
101→  let lessonsMtimeMs = null;
102→  try {
103→    lessonsMtimeMs = fs.statSync(lessonsPath).mtimeMs;
104→  } catch (_err) {
105→    return { updated: false, lessonsMtimeMs: null, reason: 'lessons-missing' };
106→  }
107→
108→  let startMs = null;
109→  if (firstTimestamp) {
110→    const parsed = Date.parse(firstTimestamp);
111→    if (!Number.isNaN(parsed)) startMs = parsed;
112→  }
113→
114→  if (startMs !== null) {
115→    return {
116→      updated: lessonsMtimeMs >= startMs,
117→      lessonsMtimeMs,
118→      reason: 'timestamp-window',
119→    };
120→  }
121→
122→  // Fallback: 4-hour window from now
123→  return {
124→    updated: now - lessonsMtimeMs < FOUR_HOURS_MS,
125→    lessonsMtimeMs,
126→    reason: 'fallback-4h',
127→  };
128→}
129→
130→/**
131→ * Derive the Claude Code project slug from a working directory path.
132→ * Matches Claude Code's on-disk layout — the leading "/" of an absolute
133→ * path becomes the single leading "-" of the slug, e.g.
134→ *   /Users/foo/projects/Bar  →  -Users-foo-projects-Bar
135→ * Trailing slashes are stripped first.
136→ */
137→function deriveSlug(cwd) {
138→  let normalized = String(cwd || '');
139→  while (normalized.length > 1 && normalized.endsWith('/')) {
140→    normalized = normalized.slice(0, -1);
141→  }
142→  return normalized.replaceAll('/', '-');
143→}
144→
145→/**
146→ * Parse a JSONL transcript string into a list of {role, content} messages
147→ * plus the first line's timestamp (if any). Malformed lines are skipped.
148→ *
149→ * @param {string} raw
150→ * @returns {{messages: Array<{role: string, content: string}>, firstTimestamp: string|null}}
151→ */
152→function parseTranscript(raw) {
153→  const messages = [];
154→  let firstTimestamp = null;
155→  if (!raw) return { messages, firstTimestamp };
156→
157→  const lines = raw.split('\n');
158→  for (let i = 0; i < lines.length; i++) {
159→    const line = lines[i].trim();
160→    if (!line) continue;
161→    let obj;
162→    try {
163→      obj = JSON.parse(line);
164→    } catch (_err) {
165→      continue;
166→    }
167→
168→    if (firstTimestamp === null) {
169→      firstTimestamp = obj.timestamp || obj.ts || null;
170→    }
171→
172→    // Claude Code transcripts: {type: "user"|"assistant", message: {role, content}}
173→    // Also support simpler {role, content} shapes for tests.
174→    const role = obj.role || (obj.message && obj.message.role) || obj.type;
175→    if (role !== 'user' && role !== 'assistant') continue;
176→
177→    const rawContent = obj.content !== undefined
178→      ? obj.content
179→      : (obj.message && obj.message.content);
180→
181→    let contentText = '';
182→    if (typeof rawContent === 'string') {
183→      contentText = rawContent;
184→    } else if (Array.isArray(rawContent)) {
185→      contentText = rawContent
186→        .map(part => (typeof part === 'string' ? part : (part && part.text) || ''))
187→        .join('\n');
188→    }
189→    messages.push({ role, content: contentText });
190→  }
191→
192→  return { messages, firstTimestamp };
193→}
194→
195→// ---------- Transcript location ----------
196→
197→function findFallbackTranscript(cwd) {
198→  const slug = deriveSlug(cwd);
199→  const dir = path.join(os.homedir(), '.claude', 'projects', slug);
200→  let entries;
201→  try {
202→    entries = fs.readdirSync(dir);
203→  } catch (_err) {
204→    return null;
205→  }
206→  const jsonls = entries
207→    .filter(n => n.endsWith('.jsonl'))
208→    .map(n => {
209→      const full = path.join(dir, n);
210→      try {
211→        return { full, mtime: fs.statSync(full).mtimeMs };
212→      } catch (_err) {
213→        return null;
214→      }
215→    })
216→    .filter(Boolean)
217→    .sort((a, b) => b.mtime - a.mtime);
218→  return jsonls.length ? jsonls[0].full : null;
219→}
220→
221→// ---------- Session Exemptions check ----------
222→
223→function hasValidExemption(lessonsPath, firstTimestamp, now = Date.now()) {
224→  let raw;
225→  try {
226→    raw = fs.readFileSync(lessonsPath, 'utf8');
227→  } catch (_err) {
228→    return false;
229→  }
230→  if (!/^##\s+Session Exemptions/im.test(raw)) return false;
231→  const { updated } = checkLessonsWindow(lessonsPath, firstTimestamp, now);
232→  return updated;
233→}
234→
235→// ---------- Debug log ----------
236→
237→function writeDebugLog(entry) {
238→  try {
239→    const logPath = path.join(process.cwd(), '.claude', 'hooks', 'lesson-capture-gate.log');
240→    fs.mkdirSync(path.dirname(logPath), { recursive: true });
241→    fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');
242→  } catch (_err) {
243→    // Logging must never block the hook
244→  }
245→}
246→
247→// ---------- Main ----------
248→
249→function main() {
250→  // Read JSON payload from stdin
251→  let payload = {};
252→  try {
253→    const raw = fs.readFileSync(0, 'utf8');
254→    if (raw.trim()) payload = JSON.parse(raw);
255→  } catch (_err) {
256→    payload = {};
257→  }
258→
259→  const cwd = process.cwd();
260→  let transcriptPath = payload.transcript_path || null;
261→  if (!transcriptPath || !fs.existsSync(transcriptPath)) {
262→    transcriptPath = findFallbackTranscript(cwd);
263→  }
264→
265→  if (!transcriptPath) {
266→    process.stderr.write('lesson-capture-gate: no transcript found, skipping scan\n');
267→    writeDebugLog({
268→      ts: new Date().toISOString(),
269→      signals: 0,
270→      lessons_mtime: null,
271→      transcript: null,
272→      decision: 'allow',
273→      reason: 'no-transcript',
274→    });
275→    process.exit(0);
276→  }
277→
278→  let transcriptRaw;
279→  try {
280→    transcriptRaw = fs.readFileSync(transcriptPath, 'utf8');
281→  } catch (_err) {
282→    process.stderr.write('lesson-capture-gate: transcript unreadable, skipping scan\n');
283→    writeDebugLog({
284→      ts: new Date().toISOString(),
285→      signals: 0,
286→      lessons_mtime: null,
287→      transcript: transcriptPath,
288→      decision: 'allow',
289→      reason: 'transcript-unreadable',
290→    });
291→    process.exit(0);
292→  }
293→
294→  const { messages, firstTimestamp } = parseTranscript(transcriptRaw);
295→  const signals = countSignals(messages);
296→  const lessonsPath = path.join(cwd, 'tasks', 'lessons.md');
297→  const { updated, lessonsMtimeMs } = checkLessonsWindow(lessonsPath, firstTimestamp);
298→
299→  if (signals === 0) {
300→    writeDebugLog({
301→      ts: new Date().toISOString(),
302→      signals,
303→      lessons_mtime: lessonsMtimeMs,
304→      transcript: transcriptPath,
305→      decision: 'allow',
306→      reason: 'no-signals',
307→    });
308→    process.exit(0);
309→  }
310→
311→  if (updated) {
312→    writeDebugLog({
313→      ts: new Date().toISOString(),
314→      signals,
315→      lessons_mtime: lessonsMtimeMs,
316→      transcript: transcriptPath,
317→      decision: 'allow',
318→      reason: 'lessons-updated',
319→    });
320→    process.exit(0);
321→  }
322→
323→  if (hasValidExemption(lessonsPath, firstTimestamp)) {
324→    writeDebugLog({
325→      ts: new Date().toISOString(),
326→      signals,
327→      lessons_mtime: lessonsMtimeMs,
328→      transcript: transcriptPath,
329→      decision: 'allow',
330→      reason: 'session-exemption',
331→    });
332→    process.exit(0);
333→  }
334→
335→  const msg =
336→    `LESSON CAPTURE GATE: ${signals} correction signals detected in this session ` +
337→    `and tasks/lessons.md has no new entries.\n` +
338→    `Run the lesson-capture subagent before closing the session:\n` +
339→    `  Task tool → lesson-capture-subagent\n` +
340→    `Or append a single-line justification to tasks/lessons.md under a ` +
341→    `"## Session Exemptions" section.\n`;
342→  process.stderr.write(msg);
343→  writeDebugLog({
344→    ts: new Date().toISOString(),
345→    signals,
346→    lessons_mtime: lessonsMtimeMs,
347→    transcript: transcriptPath,
348→    decision: 'block',
349→    reason: 'signals-no-capture',
350→  });
351→  process.exit(2);
352→}
353→
354→// ---------- Exports for tests ----------
355→
356→exports.stripCode = stripCode;
357→exports.countSignals = countSignals;
358→exports.checkLessonsWindow = checkLessonsWindow;
359→exports.deriveSlug = deriveSlug;
360→exports.parseTranscript = parseTranscript;
361→
362→if (require.main === module) {
363→  main();
364→}
365→

  1→'use strict';
  2→
  3→const test = require('node:test');
  4→const assert = require('node:assert/strict');
  5→const fs = require('fs');
  6→const path = require('path');
  7→const os = require('os');
  8→const { spawnSync } = require('child_process');
  9→
 10→const HOOK_PATH = path.resolve(__dirname, '..', '.claude', 'hooks', 'lesson-capture-gate.cjs');
 11→const {
 12→  stripCode,
 13→  countSignals,
 14→  checkLessonsWindow,
 15→  deriveSlug,
 16→  parseTranscript,
 17→} = require(HOOK_PATH);
 18→
 19→// ---------- Fixture helpers ----------
 20→
 21→function makeSandbox() {
 22→  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lcg-'));
 23→  fs.mkdirSync(path.join(dir, 'tasks'), { recursive: true });
 24→  fs.mkdirSync(path.join(dir, '.claude', 'hooks'), { recursive: true });
 25→  return dir;
 26→}
 27→
 28→function writeLessons(dir, content, mtimeMs) {
 29→  const p = path.join(dir, 'tasks', 'lessons.md');
 30→  fs.writeFileSync(p, content);
 31→  if (mtimeMs !== undefined) {
 32→    const t = new Date(mtimeMs);
 33→    fs.utimesSync(p, t, t);
 34→  }
 35→  return p;
 36→}
 37→
 38→function writeTranscript(dir, lines) {
 39→  const p = path.join(dir, 'transcript.jsonl');
 40→  fs.writeFileSync(p, lines.map(l => (typeof l === 'string' ? l : JSON.stringify(l))).join('\n'));
 41→  return p;
 42→}
 43→
 44→function runHook(dir, payload) {
 45→  return spawnSync('node', [HOOK_PATH], {
 46→    cwd: dir,
 47→    input: JSON.stringify(payload || {}),
 48→    encoding: 'utf8',
 49→  });
 50→}
 51→
 52→function userMsg(text, ts) {
 53→  const o = { type: 'user', message: { role: 'user', content: text } };
 54→  if (ts) o.timestamp = ts;
 55→  return o;
 56→}
 57→
 58→function asstMsg(text, ts) {
 59→  const o = { type: 'assistant', message: { role: 'assistant', content: text } };
 60→  if (ts) o.timestamp = ts;
 61→  return o;
 62→}
 63→
 64→// ---------- Pure function tests ----------
 65→
 66→test('stripCode removes triple-backtick fenced blocks', () => {
 67→  const input = "before ```\nyou're wrong\n``` after";
 68→  assert.ok(!stripCode(input).toLowerCase().includes("you're wrong"));
 69→});
 70→
 71→test('stripCode removes triple-tilde fenced blocks', () => {
 72→  const input = "before ~~~\nyou're wrong\n~~~ after";
 73→  assert.ok(!stripCode(input).toLowerCase().includes("you're wrong"));
 74→});
 75→
 76→test('stripCode removes inline backtick spans', () => {
 77→  const input = "before `no,` after";
 78→  assert.ok(!stripCode(input).toLowerCase().includes('no,'));
 79→});
 80→
 81→test('deriveSlug: basic cwd', () => {
 82→  assert.equal(deriveSlug('/Users/foo/projects/Bar'), '-Users-foo-projects-Bar');
 83→});
 84→
 85→test('deriveSlug: trailing slash is stripped', () => {
 86→  assert.equal(deriveSlug('/Users/foo/projects/Bar/'), '-Users-foo-projects-Bar');
 87→});
 88→
 89→test('countSignals: dedup within a single message', () => {
 90→  const msgs = [
 91→    { role: 'user', content: "you're wrong you're wrong you're wrong you're wrong you're wrong" },
 92→  ];
 93→  assert.equal(countSignals(msgs), 1);
 94→});
 95→
 96→test('countSignals: case-insensitive match', () => {
 97→  const lower = countSignals([{ role: 'user', content: "you're wrong" }]);
 98→  const upper = countSignals([{ role: 'user', content: "YOU'RE WRONG" }]);
 99→  assert.equal(lower, 1);
100→  assert.equal(upper, 1);
101→});
102→
103→test('countSignals: sums across user and assistant turns', () => {
104→  const msgs = [
105→    { role: 'user', content: "that's wrong" },
106→    { role: 'assistant', content: "my mistake, let me fix this" },
107→  ];
108→  // user: "that's wrong" = 1; assistant: "my mistake" + "let me fix" = 2
109→  assert.equal(countSignals(msgs), 3);
110→});
111→
112→test('countSignals: fenced code with signal is ignored', () => {
113→  const msgs = [
114→    { role: 'user', content: "here is the log: ```\nError: you're wrong input\n```" },
115→  ];
116→  assert.equal(countSignals(msgs), 0);
117→});
118→
119→test('parseTranscript: skips malformed JSON lines without crashing', () => {
120→  const raw = [
121→    JSON.stringify(userMsg("that's wrong", '2026-04-09T10:00:00Z')),
122→    '{ not valid json',
123→    JSON.stringify(asstMsg('my mistake')),
124→  ].join('\n');
125→  const { messages, firstTimestamp } = parseTranscript(raw);
126→  assert.equal(messages.length, 2);
127→  assert.equal(firstTimestamp, '2026-04-09T10:00:00Z');
128→});
129→
130→test('parseTranscript: empty input yields no messages', () => {
131→  const { messages, firstTimestamp } = parseTranscript('');
132→  assert.equal(messages.length, 0);
133→  assert.equal(firstTimestamp, null);
134→});
135→
136→test('checkLessonsWindow: unparseable timestamp falls back to 4h window', () => {
137→  const dir = makeSandbox();
138→  const now = Date.now();
139→  const lessonsPath = writeLessons(dir, '# Lessons\n', now - 60 * 1000);
140→  const res = checkLessonsWindow(lessonsPath, 'not-a-date', now);
141→  assert.equal(res.reason, 'fallback-4h');
142→  assert.equal(res.updated, true);
143→});
144→
145→test('checkLessonsWindow: >4h old with unparseable timestamp is not updated', () => {
146→  const dir = makeSandbox();
147→  const now = Date.now();
148→  const lessonsPath = writeLessons(dir, '# Lessons\n', now - 5 * 3600 * 1000);
149→  const res = checkLessonsWindow(lessonsPath, null, now);
150→  assert.equal(res.reason, 'fallback-4h');
151→  assert.equal(res.updated, false);
152→});
153→
154→// ---------- Integration tests (spawned hook) ----------
155→
156→test('zero correction signals → exit 0', () => {
157→  const dir = makeSandbox();
158→  writeLessons(dir, '# Lessons\n', Date.now() - 10 * 3600 * 1000);
159→  const transcript = writeTranscript(dir, [
160→    userMsg('please add a feature', '2026-04-09T10:00:00Z'),
161→    asstMsg('done'),
162→  ]);
163→  const res = runHook(dir, { transcript_path: transcript });
164→  assert.equal(res.status, 0, res.stderr);
165→});
166→
167→test('signals present + lessons newer than transcript start → exit 0', () => {
168→  const dir = makeSandbox();
169→  // Transcript says session started at T0; lessons.md is newer.
170→  const sessionStart = Date.parse('2026-04-09T10:00:00Z');
171→  writeLessons(dir, '# Lessons\n- learned something new\n', sessionStart + 60 * 1000);
172→  const transcript = writeTranscript(dir, [
173→    userMsg("you're wrong", '2026-04-09T10:00:00Z'),
174→    asstMsg('fixed'),
175→  ]);
176→  const res = runHook(dir, { transcript_path: transcript });
177→  assert.equal(res.status, 0, res.stderr);
178→});
179→
180→test('signals present + lessons unchanged in session → exit 2', () => {
181→  const dir = makeSandbox();
